// Extract the JSON object from the AI reply (it may add extra text or code fences).
const raw = String($input.first().json.text ?? '');
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start === -1 || end <= start) {
  throw new Error('No JSON found in AI response: ' + raw.slice(0, 200));
}

let meeting;
try {
  meeting = JSON.parse(raw.slice(start, end + 1));
} catch (e) {
  throw new Error('Could not parse meeting JSON: ' + e.message + ' | ' + raw.slice(0, 200));
}

const teams = Array.isArray(meeting.teams)
  ? meeting.teams.map(t => String(t).trim()).filter(Boolean)
  : [];

return [
  {
    json: {
      meeting_time: meeting.meeting_time || '',
      meeting_date: meeting.meeting_date || '',
      title: meeting.title || '',
      message: meeting.message || '',
      total_teams: teams.length,
      teams
    }
  }
];
